import{_ as o,A as d,o as r,c as i,X as t,C as s}from"./chunks/framework.pSp8ynCZ.js";const f=JSON.parse('{"title":"Data sources and column mapping","titleTemplate":":title · CellPack Rust","description":"","frontmatter":{},"headers":[],"relativePath":"rust/docs/data-sources.md","filePath":"data-sources.md"}'),c={name:"rust/docs/data-sources.md"};function n(l,e,u,p,m,h){const a=d("DocDiagram");return r(),i("div",null,[e[0]||(e[0]=t('<h1 id="data-sources-and-column-mapping" tabindex="-1">Data sources and column mapping <a class="header-anchor" href="#data-sources-and-column-mapping" aria-label="Permalink to &quot;Data sources and column mapping&quot;">​</a></h1><h2 id="register-matrices" tabindex="-1">Register matrices <a class="header-anchor" href="#register-matrices" aria-label="Permalink to &quot;Register matrices&quot;">​</a></h2><p><code>DataSourceBuilder::new(vocab, page_size)</code> declares the shared vocabulary size and I/O page size. <code>add_cpk(path, to_std)</code> registers a complete matrix stream; <code>add_cpk_region(path, offset, length, to_std)</code> registers an embedded stream. <code>build()</code> returns an immutable <code>DataSource</code>, normally shared with <code>Arc</code>.</p><p><code>to_std</code> must cover every source column. Entries are distinct standard ids in <code>[0, vocab)</code>, or <code>UNMAPPED</code> for dropped columns. All registered streams must use the builder&#39;s page size: a power of two from 512 through 65536 bytes.</p><h2 id="the-application-defines-alignment" tabindex="-1">The application defines alignment <a class="header-anchor" href="#the-application-defines-alignment" aria-label="Permalink to &quot;The application defines alignment&quot;">​</a></h2><p>Suppose matrices have these column names:</p>',6)),s(a,{name:"rust-alignment"}),e[1]||(e[1]=t('<p>A schema with <code>out_ids = [1, 0]</code> requests <code>[CD3D, GATA1]</code>. CellPack composes integer maps. It does not read names, compute a union, or infer alignment.</p><p><code>CD3D</code> is missing from matrix B. In matrix A, it is present even if a particular CSR row omits it, which represents a zero value.</p><table tabindex="0"><thead><tr><th>Situation</th><th>Output</th></tr></thead><tbody><tr><td>Source matrix has the column and the row stores a value</td><td>Value converted to the schema dtype</td></tr><tr><td>Source matrix has the column but the sparse row omits it</td><td>Zero</td></tr><tr><td>Source matrix has no column for that standard id</td><td>Schema default</td></tr><tr><td>Source column is outside the output panel</td><td>Dropped</td></tr></tbody></table><p>Use <code>with_default(f64::NAN)</code> in floating-point dense outputs to distinguish missing dimensions from present zeros. <code>with_default_bytes</code> sets an exact little-endian default, including large integers.</p><h2 id="global-cell-ids" tabindex="-1">Global cell ids <a class="header-anchor" href="#global-cell-ids" aria-label="Permalink to &quot;Global cell ids&quot;">​</a></h2><p>Matrices receive consecutive <code>CellId</code> ranges in registration order. <code>DataSource::matrix_cells(index)</code> returns the matrix&#39;s first global id and row count. Sampling must produce ids in this global space.</p><p><code>CellId</code> is <code>u32</code>. The <code>.cpk</code> format&#39;s <code>u64</code> row count does not imply that one loader data source accepts arbitrary <code>u64</code> cell ids.</p><h2 id="input-identity-and-direct-i-o" tabindex="-1">Input identity and direct I/O <a class="header-anchor" href="#input-identity-and-direct-i-o" aria-label="Permalink to &quot;Input identity and direct I/O&quot;">​</a></h2><p>Registration records each file&#39;s device, inode, size, and modification time. <code>Loader::new</code> and <code>Loader::prepare</code> check that identity to reject changed inputs. Keep input files immutable during a run as well.</p><p><code>direct_io(true)</code> opens record data with <code>O_DIRECT</code>; metadata reads remain buffered. Enable it only when the filesystem and embedded-stream alignment support the required reads. Guide examples use <code>direct_io(false)</code> for portable small-file execution.</p><p>See <a href="/cellpack-docs/rust/docs/loading.html">loading</a> for a complete example. API: <a href="/cellpack-docs/rust/api/generated-loader-struct-DataSourceBuilder.html">DataSourceBuilder</a>, <a href="/cellpack-docs/rust/api/generated-loader-struct-DataSource.html">DataSource</a>.</p>',11))])}const _=o(c,[["render",n]]);export{f as __pageData,_ as default};
